import { Dialog } from "@ark-ui/react/dialog";
import { Portal } from "@ark-ui/react/portal";
import {
  type PropsWithChildren,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { name_from_heading } from "../helpers/dialog-name";
import {
  dialog_return_target,
  settle_return_target,
} from "../helpers/ejected-focus";
import { type ModalSize, modal_box } from "../helpers/modal-box";
import { watch_stripe_challenge } from "./stripe-challenge";

interface Props extends PropsWithChildren {
  classes?: string;
  /**
   * content-box geometry tier. defaults to `sm` (512px).
   *
   * `"none"` is for a dialog that is not a centered content box — the
   * dashboard's edge-anchored sidebar drawer, its only user. it brings its own
   * position and size through `classes` and takes only the stacking context
   * from here. prefer a tier.
   */
  size?: ModalSize | "none";
  open: boolean;
  onClose: () => void;
  /**
   * fired once the close animation has finished and the content is unmounted.
   * for a caller that owns this dialog's own mount and has to hold it until
   * then.
   */
  onExitComplete?: () => void;
  /**
   * the dialog's accessible name, read to screen readers only. without it the
   * dialog is named by the first `h1`–`h6` in its content.
   */
  title?: string;
  /**
   * holds the dialog open against Escape and outside clicks, e.g. mid-submit.
   * a `Dialog.CloseTrigger` in the content, or the caller's own close
   * controls, still close it — those stay the caller's to disable.
   */
  busy?: boolean;
  /**
   * while open, a stripe 3ds or financial connections frame that stripe
   * appends to `document.body` stays on body and stays usable over this
   * dialog: clicks reach it, focus is not pulled back, and escape or a scrim
   * click does not close. off unless a caller opts in — other dialogs leave
   * those frames to the page.
   */
  adoptStripeChallenge?: boolean;
  /**
   * where focus goes at close when the element that had it at open has since
   * left the document (a row the dialog's own action removed, a list reload
   * that remounted it), or nothing had it. called once per close, against the
   * DOM as it stands then; never while that element is still connected. an
   * element that isn't focusable on its own (a table cell, a heading) holds a
   * tab stop only while focused. `null` leaves focus to zag, which has no
   * live element left to return to, so it lands on `<body>`.
   */
  returnFocusFallback?: () => HTMLElement | null;
  /** element focused when the dialog opens. zag's trap uses it when trap focus is on. */
  initialFocusEl?: () => HTMLElement | null;
}
export function Modal({
  size = "sm",
  busy = false,
  adoptStripeChallenge = false,
  ...props
}: Props) {
  const title_id = useId();
  const content_id = useId();
  const name_ref = useMemo(() => name_from_heading(title_id), [title_id]);
  const [challenge, set_challenge] = useState(false);
  // zag records its own return target a frame after opening; by then a form
  // that raised this from its submit handler has its submit button disabled
  // and focus on `<body>`
  const return_to = useRef<HTMLElement | null>(null);
  useLayoutEffect(() => {
    if (props.open) return_to.current = dialog_return_target();
  }, [props.open]);
  useLayoutEffect(() => {
    if (!props.open || !adoptStripeChallenge) return;
    return watch_stripe_challenge(set_challenge);
  }, [props.open, adoptStripeChallenge]);
  return (
    <Dialog.Root
      ids={{ title: title_id, content: content_id }}
      finalFocusEl={() =>
        settle_return_target(
          return_to.current,
          document.getElementById(content_id),
          props.returnFocusFallback
        )
      }
      open={props.open}
      initialFocusEl={props.initialFocusEl}
      // zag arms the trap on open and does not re-run it when this changes.
      // watch_stripe_challenge keeps focus in the frame while one is up.
      trapFocus={!challenge}
      closeOnEscape={!busy && !challenge}
      closeOnInteractOutside={!busy && !challenge}
      onOpenChange={(e) => {
        if (!e.open) props.onClose();
      }}
      lazyMount
      unmountOnExit
      onExitComplete={props.onExitComplete}
    >
      <Portal>
        <Dialog.Backdrop className="fixed inset-0 bg-overlay z-scrim data-[state=open]:animate-overlay-in data-[state=closed]:animate-overlay-out" />
        <Dialog.Positioner className="contents">
          <Dialog.Content
            ref={props.title ? undefined : name_ref}
            className={`data-[state=open]:animate-popup-in data-[state=closed]:animate-popup-out ${size === "none" ? "z-modal" : modal_box[size]} ${props.classes ?? ""}`}
          >
            {props.title && (
              <Dialog.Title className="sr-only">{props.title}</Dialog.Title>
            )}
            {props.children}
          </Dialog.Content>
        </Dialog.Positioner>
      </Portal>
    </Dialog.Root>
  );
}

// the payment element's controller iframe is also named `__privateStripeFrame`
// and served from js.stripe.com. that name alone is not a challenge.
const CHALLENGE =
  /three-ds-2-challenge|three-d-secure|linked-accounts|financial-connections/i;

function is_challenge_frame(frame: HTMLIFrameElement): boolean {
  const fields = [
    frame.getAttribute("src"),
    frame.getAttribute("name"),
    frame.getAttribute("id"),
    frame.getAttribute("title"),
  ];
  return fields.some(
    (value) => value != null && value !== "" && CHALLENGE.test(value)
  );
}

function is_challenge_root(node: Element): boolean {
  if (node instanceof HTMLIFrameElement) return is_challenge_frame(node);
  for (const frame of node.querySelectorAll("iframe")) {
    if (is_challenge_frame(frame)) return true;
  }
  return false;
}

function event_target_node(event: Event): Node | null {
  const target = event.target;
  return target instanceof Node ? target : null;
}

/**
 * while a donate dialog is open, a 3ds / financial-connections frame stripe
 * appends to `document.body` stays a body child. the donate box is translated,
 * and that transform is the containing block for `position: fixed`, so moving
 * the frame into the dialog clips a viewport-sized overlay to the box.
 *
 * `pointer-events: none` on `body` is inherited by a later sibling, so the
 * frame needs its own `pointer-events: auto`. `on_present` flips only when a
 * matching body child appears or leaves; the dialog uses that to ignore
 * escape and scrim clicks. those two are read when the event fires.
 *
 * the focus trap is not. `@zag-js/dialog` runs `trapFocus` on entering open
 * and does not run it again when the prop changes, so the trap stays armed.
 * the keydown listener is what keeps tab from being wrapped away from the
 * frame.
 */
export function watch_stripe_challenge(
  on_present: (present: boolean) => void
): () => void {
  const body = document.body;
  const held = new Set<HTMLElement>();
  let present = false;

  const publish = () => {
    const next = held.size > 0;
    if (next === present) return;
    present = next;
    on_present(next);
  };

  const release = (node: HTMLElement) => {
    if (!held.delete(node)) return;
    node.style.pointerEvents = "";
    publish();
  };

  const claim = (node: Element) => {
    if (!(node instanceof HTMLElement)) return;
    if (held.has(node) || node.parentElement !== body) return;
    if (!is_challenge_root(node)) return;
    node.style.pointerEvents = "auto";
    held.add(node);
    publish();
  };

  const inside = (event: Event) => {
    const target = event_target_node(event);
    if (!target) return false;
    for (const node of held) {
      if (node === target || node.contains(target)) return true;
    }
    return false;
  };

  const on_focus = (event: FocusEvent) => {
    if (inside(event)) event.stopPropagation();
  };
  // window capture runs before zag's document capture listener, which
  // preventDefaults Tab and wraps it inside the dialog. stopping every Tab
  // while a challenge is up leaves the browser's own order, so the frame
  // appended after the dialog is reachable. a keydown inside a cross-origin
  // frame never arrives here.
  const on_key = (event: KeyboardEvent) => {
    if (event.key !== "Tab" || held.size === 0) return;
    event.stopPropagation();
  };

  window.addEventListener("focusin", on_focus, true);
  window.addEventListener("keydown", on_key, true);

  const scan = () => {
    for (const node of [...held]) {
      if (
        !node.isConnected ||
        node.parentElement !== body ||
        !is_challenge_root(node)
      ) {
        release(node);
        continue;
      }
      // stripe wipes the inline value after the frame mounts. the frame
      // then inherits `pointer-events: none` from body and stops taking clicks.
      if (node.style.pointerEvents !== "auto")
        node.style.pointerEvents = "auto";
    }
    for (const child of body.children) claim(child);
  };

  // childList sees a frame appended with its src already set. a src, name,
  // id, or title that lands afterwards is an attribute record — being added
  // is not itself a match.
  const observer = new MutationObserver(scan);
  observer.observe(body, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ["src", "name", "id", "title", "style"],
  });
  scan();

  return () => {
    observer.disconnect();
    window.removeEventListener("focusin", on_focus, true);
    window.removeEventListener("keydown", on_key, true);
    for (const node of [...held]) release(node);
  };
}

const HEADING = "h1, h2, h3, h4, h5, h6";

/**
 * ref callback for a dialog content element that has no explicit title: keeps
 * `title_id` on its first `h1`–`h6`, following the content as it swaps steps.
 * pass the same id as `ids.title` on `Dialog.Root` — zag then points the
 * content's `aria-labelledby` at it, but only if an element carries that id
 * when it checks, one frame after opening. a dialog with no heading by then
 * stays unnamed: give one that opens loading a `title` instead.
 *
 * a heading that already has an id of its own is left alone (and doesn't name
 * the dialog): rewriting it would break whatever references it.
 *
 * memoize the callback per `title_id`. ark's `Dialog.Content` composes its ref
 * afresh every render, so React detaches and reattaches it on each commit; a
 * reattach to the same element within the commit keeps the one observer. a
 * detach that isn't followed by one removes the id this planted.
 */
export const name_from_heading = (title_id: string) => {
  let content: HTMLElement | null = null;
  let observer: MutationObserver | null = null;
  let planted: HTMLElement | null = null;
  let holds = 0;

  const unplant = () => {
    if (planted?.id === title_id) planted.removeAttribute("id");
    planted = null;
  };
  const sync = () => {
    const heading = content?.querySelector<HTMLElement>(HEADING) ?? null;
    if (heading === planted) return;
    unplant();
    if (heading && !heading.id) {
      heading.id = title_id;
      planted = heading;
    }
  };
  const release = () => {
    observer?.disconnect();
    observer = null;
    unplant();
    content = null;
  };

  return (el: HTMLElement | null) => {
    if (!el) return;
    if (el !== content) {
      release();
      content = el;
      sync();
      observer = new MutationObserver(sync);
      observer.observe(el, { childList: true, subtree: true });
    }
    holds++;
    return () => {
      holds--;
      queueMicrotask(() => {
        if (holds === 0) release();
      });
    };
  };
};

/**
 * per disabled `Fieldset`, the control it ejected focus from — held only while
 * that fieldset is disabled. a dialog opening in that window finds focus on
 * `<body>` and reads its return target from here instead.
 *
 * the record isn't tied to the interaction that opened the dialog: a modal
 * opened by any means while focus is on `<body>` (a mouse click in safari,
 * which doesn't focus buttons) during another form's request returns to that
 * form's control rather than to `<body>`. accepted.
 */
const ejected = new Map<HTMLFieldSetElement, HTMLElement>();

export function note_ejected(fieldset: HTMLFieldSetElement, el: HTMLElement) {
  // re-insert so iteration order is ejection order
  ejected.delete(fieldset);
  ejected.set(fieldset, el);
}

export function clear_ejected(fieldset: HTMLFieldSetElement) {
  ejected.delete(fieldset);
}

/** where a dialog opening now should send focus back to when it closes */
export function dialog_return_target(): HTMLElement | null {
  const active = document.activeElement;
  if (active instanceof HTMLElement && active !== document.body) return active;
  const latest = [...ejected.values()].reverse().find((el) => el.isConnected);
  return latest ?? null;
}

/**
 * resolves a dialog's recorded return target at close time. `null` leaves
 * focus to the dialog's default. `content` is the closing dialog's content,
 * still mounted through its exit animation. `fallback` stands in only when
 * there is no recorded target or it has left the document.
 */
export function settle_return_target(
  el: HTMLElement | null,
  content: HTMLElement | null,
  fallback?: () => HTMLElement | null
): HTMLElement | null {
  if (!el?.isConnected) {
    const stand_in = fallback?.() ?? null;
    // a cell or a heading takes focus only through a tabindex
    if (stand_in && stand_in.tabIndex < 0) remove_tab_stop_on_blur(stand_in);
    return stand_in;
  }
  if (!el.matches(":disabled")) return el;
  // a control its still-disabled fieldset ejected is refocused by that
  // fieldset on re-enabling — provided focus is on `<body>` by then, so it is
  // let go of here rather than left in the closing content
  if ([...ejected.values()].includes(el)) {
    const active = el.ownerDocument.activeElement;
    if (active instanceof HTMLElement && content?.contains(active))
      active.blur();
    return null;
  }
  const form = el.closest("form");
  if (!form) return null;
  // the dialog focuses it, with `preventScroll`
  remove_tab_stop_on_blur(form);
  return form;
}

/** `tabindex=-1` only while focused — removing it sooner would unfocus it */
export function focus_without_tab_stop(el: HTMLElement) {
  if (el.hasAttribute("tabindex")) return el.focus();
  remove_tab_stop_on_blur(el);
  el.focus();
}

function remove_tab_stop_on_blur(el: HTMLElement) {
  if (el.hasAttribute("tabindex")) return;
  el.tabIndex = -1;
  el.addEventListener("blur", () => el.removeAttribute("tabindex"), {
    once: true,
  });
}
